WITH remaining_keys AS (SELECT merchant, id FROM transactions EXCEPT SELECT merchant, id FROM transactions WHERE TO_DATE(txn_time) >= '2025-05-18'), reconciled AS (SELECT s.* FROM transactions s JOIN remaining_keys k ON s.merchant = k.merchant AND s.id = k.id) SELECT merchant, DATE_TRUNC('WEEK', txn_time) AS week_start, DATE_TRUNC('QUARTER', txn_time) AS quarter_start, SUM(amount) FILTER (WHERE txn_type = 'DEBIT') AS debit_total_amount, ROUND(AVG(amount), 2) AS avg_amount, COUNT(CASE WHEN txn_type = 'FEE' THEN 1 END) AS fee_count, COUNT(*) AS row_count, SUM(amount) FILTER (WHERE merchant = 'Grab') AS grab_total_amount, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes FROM reconciled GROUP BY ROLLUP (merchant, DATE_TRUNC('WEEK', txn_time), DATE_TRUNC('QUARTER', txn_time)) HAVING grab_total_amount > 0 ORDER BY merchant DESC NULLS FIRST;
